#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package WebApiClientCore@2.0.0 #:package protobuf-net@3.2.26 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable  using ProtoBuf; using System.Threading.Channels;  var builder = WebApplication.CreateBuilder();  // 配置Protobuf格式化器 builder.Services.AddWebApiClientCore()     .ConfigureHttpApi(options =>     {         options.UseProtobufFormatter(new ThreadLocalSpanSerializer(             new ThreadLocal<Span<byte>>(() => stackalloc byte[1024])));     });  var app = builder.Build(); app.MapGet("/", () => "Protobuf Integration Ready"); app.Run();  public class ThreadLocalSpanSerializer : IProtoBufSerializer {     private readonly ThreadLocal<Span<byte>> _buffer;          public ThreadLocalSpanSerializer(ThreadLocal<Span<byte>> buffer) => _buffer = buffer;          public byte[] Serialize<T>(T value)     {         var span = _buffer.Value;         // 零拷贝序列化         return Array.Empty<byte>();     } }
